private static Vector<URL> getJarFiles(String dir) {
  Vector<URL> jarURLs = new Vector<URL>();
  for (File file : dir.listFiles()) {
    if (file.getName().endsWith(".jar")) {
      try {
        jarURLs.add(file.toURI().toURL());
      } catch (MalformedURLException e) {
        System.err.println("Invalid URL: " + file.getAbsolutePath());
      }
    }
  }
  return jarURLs;
}

