public static void addToClassPath(Vector<URL> cpV, String dir) {
    // the collection of jar files in the specified directory
    Collection<File> jarFiles = new ArrayList<>();
    // get the URL-encoded representation of the directory path
    String encodedDir = dir.replace("\\", "/");
    // create a URL object that represents the specified directory
    URL url = new URL("file", "", encodedDir);
    // open a connection to the directory
    URLConnection connection = url.openConnection();
    // get the list of files in the directory
    Object content = connection.getContent();
    // if the list is not empty
    if (content != null) {
        // get the names of the files
        String[] fileNames = (String[]) content;
        // for each file name
        for (String fileName : fileNames) {
            // if the file name ends with .jar
            if (fileName.endsWith(".jar")) {
                // create a file object for the jar file
                File jarFile = new File(dir, fileName);
                // add the jar file to the collection
                jarFiles.add(jarFile);
            }
        }
    }
    // create a URL object for each jar file
    for (File jarFile : jarFiles) {
        // add the jar file to the vector of URLs
        cpV.add(jarFile.toURI().toURL());
    }
}

