int index = findSequence(headerPart, end, "\\r\\n");
if (index == -1) {
index = findSequence(headerPart, end, "\\r");
}
if (index == -1) {
index = findSequence(headerPart, end, "\\n");
}
return index;
}

private int findSequence(String headerPart, int end, String sequence) {
int sequenceLength = sequence.length();
if (sequenceLength == 0) {
return end;
}
for (int i = end; i < headerPart.length() - sequenceLength + 1; i++) {
boolean match = true;
for (int j = 0; j < sequenceLength; j++) {
if (headerPart.charAt(i + j) != sequence.charAt(j)) {
match = false;
break;
}
}
if (match) {
return i;
}
}
return -1;
}

