public static <V, E> IsomorphicGraphMapping<V, E> identity(Graph<V, E> graph) {
    // Initialize an IsomorphicGraphMapping for the given graph
    IsomorphicGraphMapping<V, E> mapping = new IsomorphicGraphMapping<>(graph);

    // Add an identity mapping for each vertex in the graph
    for (V vertex : graph.getVertices()) {
        mapping.addVertex(vertex, vertex);
    }

    // Add an identity mapping for each edge in the graph
    for (E edge : graph.getEdges()) {
        mapping.addEdge(edge.getSource(), edge.getTarget(), edge);
    }

    return mapping;
}

