void generateGraph(Graph<V,E> target, Map<String, V> resultMap) {
    // Create an empty bipartite graph with numLeft vertices on the left and numRight vertices on the right
    int numLeft = resultMap.size();
    int numRight = numLeft;
    final List<V> left = new ArrayList<>(numLeft);
    final List<V> right = new ArrayList<>(numRight);
    for (int i = 0; i < numLeft; i++) {
        left.add(null);
    }
    for (int i = 0; i < numRight; i++) {
        right.add(null);
    }
    target.addGraphType(new BipartiteGraph(left, right));

    // Construct the graph
    for (String key : resultMap.keySet()) {
        int leftIdx = key.hashCode() % numLeft;
        int rightIdx = key.hashCode() % numRight;
        V currLeft = left.get(leftIdx);
        V currRight = right.get(rightIdx);
        if (currLeft == null) {
            left.set(leftIdx, resultMap.get(key));
        } else if (currRight == null) {
            right.set(rightIdx, resultMap.get(key));
        } else {
            target.addEdge(new Pair<>(currLeft, currRight));
        }
    }
}

void generateGraph(Graph<V, E> target, Map<String, V> resultMap)
{
    // Initialize a queue to store thenodes to be processed
    Queue<V> nodeQueue = new ArrayDeque<>();
    // Add all nodes from the original graph to the queue
    for (V node : target.nodes) {
        nodeQueue.add(node);
    }
    while (!nodeQueue.isEmpty()) {
        // Get the node to be processed from the queue
        V node = nodeQueue.poll();
        // Add the node to the result graph
        resultMap.put(node.label, node);
        // Iterate over all edges incident to the node
        for (E edge : target.edgesIncidentTo(node)) {
            // Get the endpoints of the edge
            V sourceNode = edge.source;
            V targetNode = edge.target;
            // Check if the source node is already in the result graph
            if (!resultMap.containsKey(sourceNode.label)) {
                // Add the source node to the result graph
                resultMap.put(sourceNode.label, sourceNode);
                // Add the source node to the queue
                nodeQueue.add(sourceNode);
            }
            // Check if the target node is already in the result graph
            if (!resultMap.containsKey(targetNode.label)) {
                // Add the target node to the result graph
                resultMap.put(targetNode.label, targetNode);
                // Add the target node to the queue
                nodeQueue.add(targetNode);
            }
        }
    }
}

