public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    // Serialize the message with the specified schema
    ByteBuffer serializedMessage = schema.pack(message, buffer);

    // Compute the size of the message prefixed with its length
    int messageSize = serializedMessage.remaining();
    int totalSize = messageSize + 4;

    // Write the prefixed message to the output stream
    out.writeInt(totalSize);
    out.writeInt(messageSize);
    out.write(serializedMessage.array(), 0, messageSize);

    // Return the size of the message
    return messageSize;
}

