private static Class<?> toRawClass(Type type, Class<?> targetType) {
    if (type instanceof Class<?>) {
        return (Class<?>) type;
    } else if (type instanceof ParameterizedType) {
        ParameterizedType pt = (ParameterizedType) type;
        Class<?> rawType = (Class<?>) pt.getRawType();
        if (rawType.isAssignableFrom(targetType)) {
            return targetType;
        } else {
            Type[] genericArgs = pt.getActualTypeArguments();
            for (int i = 0; i < genericArgs.length; i++) {
                Class<?> resolvedArg = toRawClass(genericArgs[i], targetType);
                if (resolvedArg != null) {
                    return resolvedArg;
                }
            }
        }
    }
    return null;
}

public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (genericType instanceof ParameterizedType) {
        ParameterizedType parameterizedType = (ParameterizedType) genericType;
        Type[] actualTypeArguments = parameterizedType.getActualTypeArguments();
        if (actualTypeArguments.length > 0) {
            Class<?>[] resolvedArguments = new Class<?>[actualTypeArguments.length];
            for (int i = 0; i < actualTypeArguments.length; i++) {
                Type actualTypeArgument = actualTypeArguments[i];
                if (actualTypeArgument instanceof Class) {
                    resolvedArguments[i] = (Class) actualTypeArgument;
                } else if (actualTypeArgument instanceof TypeVariable) {
                    resolvedArguments[i] = resolveTypeVariable(targetType, (TypeVariable) actualTypeArgument);
                }
            }
            return resolvedArguments;
        }
    }
    return null;
}

private static Class<?> resolveTypeVariable(Class<?> targetType, TypeVariable typeVariable) {
    Map<TypeVariable, Type> typeVariableMap = getTypeVariableMap(targetType);
    Type type = typeVariableMap.get(typeVariable);
    if (type instanceof Class) {
        return (Class) type;
    } else {
        return resolveTypeVariable(targetType, (TypeVariable) type);
    }
}

