private long readSignedLong(final byte[] buffer) {
    return (buffer[0] & 0xFF) << 56 | (buffer[1] & 0xFF) << 48 | (buffer[2] & 0xFF) << 40 | (buffer[3] & 0xFF) << 32 | (buffer[4] & 0xFF) << 24 | (buffer[5] & 0xFF) << 16 | (buffer[6] & 0xFF) << 8 | buffer[7] & 0xFF;
}

private void readFully(final int offset, final byte[] buffer, final int start, final int length) {
    while (length > 0) {
        final int bytesRead = read(offset + start, buffer, start, length);
        start += bytesRead;
        length -= bytesRead;
    }
}

