public int writeTo(DataOutput out, LinkedBuffer node) throws IOException {
    int totalContentSize = 0;
    for (Object value : node.getElements()) {
        if (value instanceof LinkedBuffer) {
            totalContentSize += writeTo(out, (LinkedBuffer) value);
        } else if (value instanceof String) {
            out.writeUTF((String) value);
            totalContentSize += 2 + ((String) value).length();
        } else if (value instanceof Integer) {
            out.writeInt((int) value);
            totalContentSize += 4;
        } else if (value instanceof Long) {
            out.writeLong((long) value);
            totalContentSize += 8;
        } else if (value instanceof Double) {
            out.writeDouble((double) value);
            totalContentSize += 8;
        } else if (value instanceof Float) {
            out.writeFloat((float) value);
            totalContentSize += 4;
        } else if (value instanceof Short) {
            out.writeShort((short) value);
            totalContentSize += 2;
        } else if (value instanceof Byte) {
            out.writeByte((byte) value);
            totalContentSize += 1;
        } else if (value instanceof Character) {
            out.writeChar((char) value);
            totalContentSize += 2;
        } else {
            throw new IllegalArgumentException("Unsupported type: " + value.getClass());
        }
    }
    return totalContentSize;
}

