public static int nextPrime(int desiredCapacity) {
    /*
     * Check if the desired capacity is greater than zero. If it is,
     * return the next prime number greater than or equal to the desired capacity.
     * If the desired capacity is less than or equal to zero, return the smallest prime number.
     */
    if (desiredCapacity > 0) {
        int num = desiredCapacity;
        while (!isPrime(num)) {
            num++;
        }
        return num;
    } else {
        return 2;
    }
}

private static boolean isPrime(int num) {
    if (num <= 1) {
        return false;
