public static String unescapeJava(String str) throws Exception {
    StringBuilder sb = new StringBuilder(str.length());
    for (int i = 0; i < str.length(); i++) {
        char c = str.charAt(i);
        if (c == '\\') {
            char nextChar = (i == str.length() - 1) ? '\\' : str.charAt(i + 1);
            // Handle common case first, then the rest.
            switch (nextChar) {
                case '"':
                case '\\':
                case '/':
                    sb.append(nextChar);
                    i++;
                    break;
                case 'b':
                    sb.append('\b');
                    i++;
                    break;
                case 'f':
                    sb.append('\f');
                    i++;
                    break;
                case 'n':
                    sb.append('\n');
                    i++;
                    break;
                case 'r':
                    sb.append('\r');
                    i++;
                    break;
                case 't':
                    sb.append('\t');
                    i++;
                    break;
                case 'u':
                    sb.append((char)Integer.parseInt(str.substring(i + 2, i + 6), 16));
                    i += 5;
                    break;
                default:
                    if (nextChar == 'U') {
                        sb.append((char)Integer.parseInt(str.substring(i + 2, i + 8), 16));
                        i += 7;
                    }
            }
        } else {
            sb.append(c);
        }
    }
    return sb.toString();
}

public static String unescapeJava(String str) throws Exception {
    StringBuilder sb = new StringBuilder(str);
    for (int i = 0; i < str.length(); i++) {
        char ch = str.charAt(i);
        switch (ch) {
            case '\\':
                i++;
                if (i < str.length() && str.charAt(i) == 'n') {
                    sb.setCharAt(i - 1, '\n');
                }
                break;
            case '#':
                i++;
                if (i < str.length() && str.charAt(i) == '{') {
                    while (i < str.length() && str.charAt(i) != '}') {
                        i++;
                    }
                }
                break;
        }
    }
    return sb.toString();
}

