protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
synchronized (graph) {
if (tour==null) {
throw new IllegalArgumentException("Tour cannot be null.");
}
GraphPath<V,E> path = new GraphPath<>();
E next = null;
Iterator<E> it = tour.iterator();
while (it.hasNext()) {
E edge = it.next();
next = edge;
path.addEdge(edge);
if (edge==null) {
throw new IllegalArgumentException("The edge set cannot contain null edges.");
}
if (!graph.containsEdge(edge)) {
continue;
}
if (!graph.getEndpoints(edge).contains((V)next.getSource()) && !graph.getEndpoints(edge).contains((V)next.getTarget())) {
continue;
}
if (next.getSource() instanceof V) {
V source = (V)next.getSource();
V target = (V)next.getTarget();
if (!graph.containsVertex(source)) {
continue;
}
path.addVertex(source);
if (!graph.containsVertex(target)) {
continue;
}
path.addVertex(target);
} else {
continue;
}
}
}
return path;
}

