public static Pair<List<Integer>,Long> computeSuffixSum(List<Integer> bounds) {
    List<Integer> suffixSum = new ArrayList<>();
    long totalSum = 0;

    // Initialize suffix sum and total sum
    suffixSum.add(bounds.get(0));
    totalSum += bounds.get(0);

    for (int i = 1; i < bounds.size(); i++) {
        suffixSum.add(bounds.get(i) + suffixSum.get(i - 1));
        totalSum += bounds.get(i);
    }

    return new Pair<>(suffixSum, totalSum);
}

private Pair<List<Integer>,Long> computeSuffixSum(List<Integer> bounds) {
    List<Integer> suffixSum = new ArrayList<Integer>();
    Long sum = 0L;
    for (int i = 0; i < bounds.size(); i++) {
        suffixSum.add(bounds.get(i) + sum);
        sum += bounds.get(i);
    }
    return new Pair<List<Integer>,Long>(suffixSum, sum);
}

private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    List<Integer> suffixSum = new ArrayList<>(bounds.size());
    long sum = 0;
    for (int i = bounds.size() - 1; i >= 0; i--) {
        sum += bounds.get(i);
        suffixSum.add(sum);
    }
    return new Pair<>(suffixSum, sum);
}

