private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    // create a copy of the graph containing only the given vertices
    Graph<V,E> subgraph = graph.subgraph(vertices);

    // iterate over all pairs of vertices in the subgraph
    for (V v1 : vertices) {
        for (V v2 : vertices) {
            // if v1 and v2 are not connected in the original graph
            if (!graph.containsEdge(v1, v2)) {
                // and they are connected in the subgraph
                if (subgraph.containsEdge(v1, v2)) {
                    // then the subgraph is not a clique
                    return false;
                }
            }
        }
    }

    // if we reach this point, the subgraph is a clique
    return true;
}

