public static String applyRelativePath(String path, String relativePath) {
    if (relativePath.startsWith("/")) {
        return relativePath;
    }
    String[] pathArr = path.split("/");
    String[] relativePathArr = relativePath.split("/");
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < pathArr.length; i++) {
        sb.append(pathArr[i]).append("/");
    }
    for (String relativePathElem : relativePathArr) {
        if (relativePathElem.equals("..")) {
            sb.delete(sb.lastIndexOf("/"), sb.length());
        } else if (!relativePathElem.equals(".")) {
            sb.append(relativePathElem).append("/");
        }
    }
    return sb.toString();
}

