    int lastUnix = filename.lastIndexOf('/');
    int lastWindows = filename.lastIndexOf('\\');
    return Math.max(lastUnix, lastWindows);
}

int indexOfExtension(String filename) {
    int sep = indexOfLastSeparator(filename);
    if (sep > -1) {
        int ext = filename.lastIndexOf('.');
        if (ext > -1) {
            // Make sure last separator is not a directory separator
            if (filename.charAt(sep) == File.separatorChar || filename.charAt(sep) == '\\') {
                return -1;
            }
            return ext;
        }
    }
    return -1;
}

public int indexOfExtension(String filename) {
    int extensionIndex = filename.lastIndexOf('.');
    int lastSeparatorIndex = indexOfLastSeparator(filename);
    // check that there is no directory separator after the last dot
    return (extensionIndex >= 0 && extensionIndex > lastSeparatorIndex) ? extensionIndex : -1;
}

