public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
   // Define local variables
   BufferedReader br = null;
   List<ThreadSnapshot> threadSnapshots = new ArrayList<>();

   try {
      // Open file input stream
      br = new BufferedReader(new FileReader(file));
      String line = br.readLine();

      // Read each line of the file
      while (line != null) {
         // Split line into command and id
         String[] parts = line.split("\\s+");
         String command = parts[0];
         String id = parts[1];

         // Check if command is 'FRAME'
         if (command.equals("FRAME")) {
            // Parse data from line
            int startTime = Integer.parseInt(parts[2]);
            int endTime = Integer.parseInt(parts[3]);
            long allocation = Long.parseLong(parts[4]);
            long deallocation = Long.parseLong(parts[5]);
            byte[] signature = parts[6].getBytes();

            // Create new thread snapshot
            ThreadSnapshot snapshot = new ThreadSnapshot(Integer.parseInt(id), startTime, endTime, allocation, deallocation, signature);

            // Add snapshot to list
            threadSnapshots.add(snapshot);
         }

         // Read next line
         line = br.readLine();
      }
   } catch (Exception e) {
      // Print error message
      System.err.println("Error: " + e.getMessage());
   } finally {
      // Close file input stream
      if (br != null) {
         br.close();
      }
   }

   // Return thread snapshots
   return threadSnapshots;
}
